<div class="breadcrumb"><a href="<?= $u() ?>">Home</a><span>/</span><span>Area calculator</span></div><div class="page-intro"><div><span class="eyebrow">AREA &amp; COST CALCULATOR</span><h1>Every square foot, considered.</h1><p>Measure named surfaces, allow for cut-outs and estimate real selling quantities.</p></div></div>
<div class="planning-layout"><form class="panel" method="get" action="<?= $u('calculator') ?>" id="area-calculator"><h2>Plan your material</h2><label class="field">Material variant<select name="variant_id"><option value="">Area estimate only</option><?php foreach ($products as $product): ?><?php foreach ($product['variants'] as $choice): ?><option value="<?= $e($choice['id']) ?>" <?= $variant && (int)$variant['id'] === (int)$choice['id'] ? 'selected' : '' ?>><?= $e($product['name'].' · '.$choice['sku']) ?> · <?= $m($choice['unit_price_minor']) ?> / <?= $e($choice['sell_unit']) ?></option><?php endforeach; ?><?php endforeach; ?></select></label>
<div id="calculator-surfaces"><?php foreach (array_values($input['surfaces']) as $index=>$surface): ?><fieldset class="php-surface"><legend>Surface <?= $index+1 ?></legend><div class="form-grid"><label class="full">Name<input name="surfaces[<?= $index ?>][name]" maxlength="80" value="<?= $e($surface['name']) ?>" required></label><?php foreach (['length'=>'Length','width'=>'Width'] as $field=>$label): ?><label><?= $e($label) ?><input type="number" name="surfaces[<?= $index ?>][<?= $e($field) ?>]" min="0.001" max="1000" step="0.001" value="<?= $e($surface[$field]) ?>" required></label><?php endforeach; ?><label>Unit<select name="surfaces[<?= $index ?>][unit]"><?php foreach (['ft'=>'Feet','m'=>'Metres','in'=>'Inches'] as $unit=>$label): ?><option value="<?= $e($unit) ?>" <?= $surface['unit'] === $unit ? 'selected' : '' ?>><?= $e($label) ?></option><?php endforeach; ?></select></label><label>Cut-out area (sqft)<input type="number" min="0" max="1000000" step="0.001" name="surfaces[<?= $index ?>][cutout]" value="<?= $e($surface['cutout'] ?? '0') ?>"></label></div><button class="text-button" type="button" data-remove-surface hidden>Remove surface</button></fieldset><?php endforeach; ?></div>
<button class="button secondary" type="button" id="add-surface" hidden>Add another surface +</button><div class="form-grid"><label>Wastage<select name="waste_bps"><?php foreach ([0=>'0%',500=>'5%',1000=>'10%',1500=>'15%',2500=>'25%'] as $bps=>$label): ?><option value="<?= $bps ?>" <?= (int)$input['waste_bps'] === $bps ? 'selected' : '' ?>><?= $e($label) ?></option><?php endforeach; ?></select></label><label>Polishing estimate (INR / sqft)<input name="polish_rate" type="number" min="0" max="10000" step="0.01" value="<?= $e($input['polish_rate']) ?>"></label><label>Installation estimate (INR / net sqft)<input name="install_rate" type="number" min="0" max="10000" step="0.01" value="<?= $e($input['install_rate']) ?>"></label></div><button class="button">Calculate estimate ↗</button><p class="note">Optional labour rates are your estimates. Checkout applies the store’s actual tax/delivery policy separately.</p></form>
<aside class="panel estimate"><span class="eyebrow">YOUR PROJECT ESTIMATE</span><h2>Room for your next idea.</h2><dl><dt>Net surface area</dt><dd><?= $q($estimate['net_area_milli']) ?> sqft</dd><dt>With wastage</dt><dd><?= $q($estimate['required_area_milli']) ?> sqft</dd><?php if ($variant): ?><dt>Purchase quantity</dt><dd><?= $q($estimate['qty_milli']) ?> <?= $e($variant['sell_unit']) ?></dd><dt>Material</dt><dd><?= $m($estimate['material_minor']) ?></dd><?php endif; ?><dt>Polishing estimate</dt><dd><?= $m($estimate['polish_minor']) ?></dd><dt>Installation estimate</dt><dd><?= $m($estimate['install_minor']) ?></dd></dl><div class="estimate-total"><span><?= $variant ? 'Estimated material + labour' : 'Estimated labour only' ?></span><strong><?= $m($estimate['estimated_total_minor']) ?></strong></div><p class="note">Quantities round up to selling increments. Tax and delivery are excluded. No inventory is reserved by this estimate.</p>
<?php if ($variant): ?><form method="post" action="<?= $u('cart') ?>"><input type="hidden" name="csrf" value="<?= $e(RequestSecurity::csrfToken()) ?>"><input type="hidden" name="variant_id" value="<?= $e($variant['id']) ?>"><input type="hidden" name="cart_id" value="<?= $e($cart['id'] ?? '') ?>"><input type="hidden" name="cart_revision" value="<?= $e($cart['revision']) ?>"><input type="hidden" name="quantity" value="<?= $q($estimate['qty_milli']) ?>"><button class="button light">Set this quantity in bag ↗</button><p class="note">This replaces the selected variant’s quantity. The cart rechecks prices and stock.</p></form><?php else: ?><p class="note">Select a published material variant to estimate material costs and send its quantity to your bag.</p><?php endif; ?></aside></div>
